-- ===========================================================================
-- MediBook - Supabase Storage buckets & policies
-- Private buckets. Medical documents are only ever served through short-lived
-- signed URLs generated by the backend after an authorization check.
-- ===========================================================================
do $$
begin
  if to_regclass('storage.buckets') is null then
    raise notice 'Supabase storage schema not available - skipping bucket setup';
    return;
  end if;

  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values
    ('medical-records', 'medical-records', false, 10485760,
      array['application/pdf', 'image/jpeg', 'image/png', 'image/webp']),
    ('avatars', 'avatars', true, 2097152,
      array['image/jpeg', 'image/png', 'image/webp'])
  on conflict (id) do update
    set public = excluded.public,
        file_size_limit = excluded.file_size_limit,
        allowed_mime_types = excluded.allowed_mime_types;
end $$;

do $$
begin
  if to_regclass('storage.objects') is null then
    return;
  end if;

  drop policy if exists medibook_medical_read on storage.objects;
  create policy medibook_medical_read on storage.objects for select
  using (
    bucket_id = 'medical-records'
    and exists (
      select 1 from medical_records mr
      where mr.file_path = storage.objects.name
        and (mr.patient_id = public.current_patient_id()
             or public.doctor_treats_patient(mr.patient_id)
             or public.is_admin())
    )
  );

  drop policy if exists medibook_medical_insert on storage.objects;
  create policy medibook_medical_insert on storage.objects for insert
  with check (bucket_id = 'medical-records' and auth.uid() is not null);

  drop policy if exists medibook_avatars_public_read on storage.objects;
  create policy medibook_avatars_public_read on storage.objects for select
  using (bucket_id = 'avatars');

  drop policy if exists medibook_avatars_write on storage.objects;
  create policy medibook_avatars_write on storage.objects for insert
  with check (bucket_id = 'avatars' and auth.uid() is not null);
end $$;
